snippet_css:
:root{
  --bg: #BEDDF1;
  --fg: #1C1B29;
  --muted: #3D4A63;
  --surface: #FBF7EF;
  --border: #C6D8E6;
  --accent: #2F5C93;
  --accent-fg: #FFFFFF;
  --radius: 20px;
  --radius-sm: 12px;
  --shadow: 0 18px 40px rgba(47,92,147,.18);
  --btn-shadow: 0 6px 0 rgba(47,92,147,.30);
  --art-bg: radial-gradient(circle at 35% 35%,#FFFFFF,#FAF3E0 40%,#E8C39E);
  --media-bg: linear-gradient(#87CEEB,#BFE3F2 40%,#F7C5CC);
  --cta-bg: #EAF3FA;
  --input-bg: #FFFFFF;
  --ok: #2E7D5B;
  --warn: #B5503C;
  --font-display: 'Cormorant','Noto Serif TC',serif;
  --font-body: 'Inter','Noto Sans TC',sans-serif;
  --font-mono: 'Cormorant',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

snippet_tailwind:
// tailwind.config.js → theme.extend
{
  "colors": {
    "bg": "#BEDDF1",
    "fg": "#1C1B29",
    "muted": "#3D4A63",
    "surface": "#FBF7EF",
    "border": "#C6D8E6",
    "accent": "#2F5C93",
    "accent-fg": "#FFFFFF",
    "ok": "#2E7D5B",
    "warn": "#B5503C",
    "focus-ring": "var(--accent)"
  },
  "borderRadius": {
    "DEFAULT": "12px",
    "lg": "20px"
  },
  "fontFamily": {
